#!/usr/bin/env python3
"""
gen_sha256sums.py 鈥?Generate SHA256SUMS for a release tree
Usage: python3 gen_sha256sums.py [root_dir] [--output SHA256SUMS]
"""
import argparse
import hashlib
import os
import sys
from pathlib import Path

EXCLUDE_DIRS = {".git", "__pycache__", ".pytest_cache", "data", "reports",
                "logs", "state", "sessions", ".venv", "venv", "node_modules"}
EXCLUDE_EXTS = {".pyc", ".pyo", ".pyd", ".tmp", ".bak"}
EXCLUDE_FILES = {"SHA256SUMS"}


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def collect(root):
    root = Path(root).resolve()
    results = []
    for dirpath, dirnames, filenames in os.walk(root):
        # Prune excluded dirs in-place
        dirnames[:] = sorted(
            d for d in dirnames if d not in EXCLUDE_DIRS and not d.startswith("backup")
        )
        for fname in sorted(filenames):
            if fname in EXCLUDE_FILES:
                continue
            fpath = Path(dirpath) / fname
            rel = fpath.relative_to(root)
            if fpath.suffix in EXCLUDE_EXTS:
                continue
            results.append((str(rel).replace("\\", "/"), fpath))
    return results


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("root", nargs="?", default=".")
    ap.add_argument("--output", default="SHA256SUMS")
    args = ap.parse_args()

    files = collect(args.root)
    lines = []
    for rel, path in files:
        digest = sha256_file(path)
        lines.append(f"{digest}  {rel}")
    output = Path(args.root) / args.output
    output.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"SHA256SUMS written: {output} ({len(lines)} entries)")


if __name__ == "__main__":
    main()

